103:      const ws = new WebSocket(`ws://127.0.0.1:${lock.port}/`);
104:      this.ws = ws;
105:      let stage: "challenge" | "welcome" | "done" = "challenge";
106:      let failed = false;
107:      const fail = (e: Error) => {
