149:          return;
150:        }
151:        if (stage === "welcome") {
152:          if (msg.type !== "welcome") return fail(new Error(`handshake violation: expected welcome, got ${String(msg.type)}`));
153:          if (msg.pid !== lock.pid || msg.nonce !== lock.nonce || msg.protocolVersion !== protocolVersion || msg.role !== role) {
