181:        this.gaps++;
182:        this.opts.onGap?.(this.lastSeq + 1, e.seq);
183:        // 이 소켓은 더 믿지 않는다: 나머지 배치를 버리고 재구독
184:        if (this.ws === ws) {
185:          this.ws = undefined;
186:          this.connected = false;
187:          for (const p of this.pending.values()) p.reject(new RpcCallError(-32000, "resubscribing after seq gap"));
188:          this.pending.clear();
189:        }
190:        try {
191:          ws.terminate();
192:        } catch {
193:          /* ignore */
194:        }
195:        if (this.opening) this.gapDuringOpen = true; // open() 이 재시도한다
196:        else void this.autoReconnect();
197:        return;
198:      }
199:      this.lastSeq = e.seq;
200:      this.opts.onEvent(e);
201:    }
202:  }
203:
204:  /** 갭 뒤 제한 재시도; 모두 실패하면 onDisconnect 로 알리고 connected=false 로 남는다(호출자가 reconnect() 로 재개) */
205:  private async autoReconnect(): Promise<void> {
206:    for (let attempt = 1; attempt <= AUTO_RECONNECT_ATTEMPTS; attempt++) {
207:      if (this.closedByUser) return;
208:      try {
209:        await this.reconnect();
210:        return;
211:      } catch {
212:        if (attempt < AUTO_RECONNECT_ATTEMPTS) await new Promise((r) => setTimeout(r, AUTO_RECONNECT_DELAY_MS));
213:      }
214:    }
215:    if (!this.closedByUser) this.opts.onDisconnect?.();
