218:  call<T = unknown>(method: RpcMethod | string, params?: unknown): Promise<T> {
219:    const ws = this.ws;
220:    if (!ws || !this.connected || ws.readyState !== WebSocket.OPEN) return Promise.reject(new RpcCallError(-32000, "not connected"));
