252:  close(): void {
253:    this.closedByUser = true;
254:    const ws = this.ws;
255:    this.ws = undefined;
256:    this.connected = false;
257:    try {
258:      ws?.close(1000, "client close");
259:    } catch {
260:      /* ignore */
261:    }
262:  }
263:}

