.github/workflows/ci.yml:16:        with:
.github/workflows/ci.yml:17:          node-version: 24
.github/workflows/ci.yml:18:          cache: npm
.github/workflows/ci.yml:19:      - run: npm ci
.github/workflows/ci.yml:20:      - run: npm run lint
.github/workflows/ci.yml:21:      - name: renderer + shell bundles (P01 T6/T7 — CSP meta·CJS main/preload 가 빌드된다)
.github/workflows/ci.yml:22:        run: npm run renderer:build && npm run shell:build
.github/workflows/ci.yml:23:      - run: npm test
.github/workflows/ci.yml:24:      - name: daemon self-test (P01 T2 — detached entry boots, writes lock, answers daemon.status, exits 0)
.github/workflows/ci.yml:25:        run: npm run daemon -- --dir "${{ runner.temp }}/as-daemon" --token-store file --self-test
.github/workflows/ci.yml:26:  codex-schema-diff:
.github/workflows/ci.yml:27:    # P01 T10: codex app-server 스키마 재생성 diff. codex npm 패키지를 받을 수 없으면 성공으로 위장하지 않고 UNVERIFIED 로 요약한다.
.github/workflows/ci.yml:28:    runs-on: ubuntu-latest
.github/workflows/ci.yml:29:    steps:
.github/workflows/ci.yml:30:      - uses: actions/checkout@v4
.github/workflows/ci.yml:31:      - uses: actions/setup-node@v4
.github/workflows/ci.yml:32:        with:
.github/workflows/ci.yml:33:          node-version: 24
.github/workflows/ci.yml:34:          cache: npm
.github/workflows/ci.yml:35:      - run: npm ci
.github/workflows/ci.yml:36:      - name: schema diff (codex-cli 0.166.0 via npx)
.github/workflows/ci.yml:37:        shell: bash
.github/workflows/ci.yml:38:        run: |
.github/workflows/ci.yml:39:          set -uo pipefail
.github/workflows/ci.yml:40:          if VER=$(npx -y @openai/codex@0.166.0 --version 2>/dev/null); then
.github/workflows/ci.yml:41:            echo "codex: $VER"
.github/workflows/ci.yml:42:            mkdir -p "$RUNNER_TEMP/codexbin"
.github/workflows/ci.yml:43:            printf '#!/usr/bin/env bash\nexec npx -y @openai/codex@0.166.0 "$@"\n' > "$RUNNER_TEMP/codexbin/codex"
.github/workflows/ci.yml:44:            chmod +x "$RUNNER_TEMP/codexbin/codex"
.github/workflows/ci.yml:45:            if PATH="$RUNNER_TEMP/codexbin:$PATH" npm run schema:diff; then
.github/workflows/ci.yml:46:              echo "schema-diff: VERIFIED ($VER)" >> "$GITHUB_STEP_SUMMARY"
.github/workflows/ci.yml:47:            else
.github/workflows/ci.yml:48:              echo "schema-diff: FAILED ($VER) — bundle differs from regenerated schema" >> "$GITHUB_STEP_SUMMARY"
.github/workflows/ci.yml:49:              exit 1
.github/workflows/ci.yml:50:            fi
.github/workflows/ci.yml:51:          else
.github/workflows/ci.yml:52:            echo "::warning::codex npm 0.166.0 unavailable — schema diff UNVERIFIED"
.github/workflows/ci.yml:53:            echo "schema-diff: UNVERIFIED (codex npm package unavailable in CI)" >> "$GITHUB_STEP_SUMMARY"
.github/workflows/ci.yml:54:          fi
