9:import { Ajv } from "ajv";
10:import type { JournalEvent } from "./events.js";
11:import { TASK_KINDS } from "./events.js";
12:
13:export const RPC_PROTOCOL_VERSION = 1;
14:
15:export const RPC_METHODS = {
16:  read: ["daemon.status", "events.subscribe", "task.get", "task.list", "approval.pending", "policy.get", "capabilities.get"],
17:  write: ["task.submit", "task.cancel", "task.unblock", "task.abandon", "approval.decide", "policy.set", "user_input.answer"],
18:  control: ["daemon.shutdown"],
19:} as const;
20:export type RpcMethodClass = keyof typeof RPC_METHODS;
21:export type RpcReadMethod = (typeof RPC_METHODS.read)[number];
22:export type RpcWriteMethod = (typeof RPC_METHODS.write)[number];
23:export type RpcControlMethod = (typeof RPC_METHODS.control)[number];
24:export type RpcMethod = RpcReadMethod | RpcWriteMethod | RpcControlMethod;
25:
26:export const RPC_ERRORS = {
27:  METHOD_NOT_FOUND: -32601,
28:  INVALID_PARAMS: -32602,
29:  UNAUTHORIZED: -32001,
30:  STALE_WRITER: -32003,
31:  PRECONDITION_FAILED: -32004,
32:  APPROVAL_ERROR: -32005,
33:  NOT_PENDING: -32006,
34:} as const;
35:/** JSON-RPC ?��?: ?�청 ?�식 ?�류·?��? ?�류 */
36:export const RPC_INVALID_REQUEST = -32600;
37:export const RPC_INTERNAL_ERROR = -32000;
38:
39:export type RpcId = number | string;
40:export interface RpcRequest {
41:  jsonrpc: "2.0";
42:  id: RpcId;
43:  method: string;
44:  params?: unknown;
45:}
46:export interface RpcError {
47:  code: number;
48:  message: string;
49:  data?: unknown;
50:}
51:export type RpcResponse = { jsonrpc: "2.0"; id: RpcId | null; result: unknown } | { jsonrpc: "2.0"; id: RpcId | null; error: RpcError };
52:export interface RpcEventsBatch {
53:  jsonrpc: "2.0";
54:  method: "events.batch";
55:  params: { events: JournalEvent[] };
56:}
57:
58:export type JsonSchema = Record<string, unknown>;
59:
60:const obj = (properties: Record<string, JsonSchema>, required: string[] = []): JsonSchema => ({ type: "object", additionalProperties: false, required, properties });
61:const EMPTY = obj({});
62:const ID = { type: "string", minLength: 1 } as const;
63:const COMBO = obj({ provider: { enum: ["claude", "codex"] }, os: { type: "string", minLength: 1 }, sandbox: { type: "string", minLength: 1 }, variant: { type: "string", minLength: 1 } }, ["provider", "os", "sandbox", "variant"]);
64:
65:export const RPC_PARAMS_SCHEMA: Record<RpcMethod, JsonSchema> = {
66:  "daemon.status": EMPTY,
67:  "events.subscribe": obj({ fromSeq: { type: "integer", minimum: 0 } }, ["fromSeq"]),
68:  "task.get": obj({ taskId: ID }, ["taskId"]),
69:  "task.list": EMPTY,
70:  "approval.pending": EMPTY,
71:  "policy.get": obj({ projectId: ID }),
72:  "capabilities.get": EMPTY,
73:  "task.submit": obj({ title: { type: "string", minLength: 1, maxLength: 200 }, kind: { enum: [...TASK_KINDS] }, phaseId: ID }, ["title", "kind"]),
74:  "task.cancel": obj({ taskId: ID }, ["taskId"]),
75:  "task.unblock": obj({ taskId: ID }, ["taskId"]),
76:  "task.abandon": obj({ taskId: ID }, ["taskId"]),
77:  "approval.decide": obj({ requestId: ID, decision: { enum: ["accept", "decline", "cancel"] }, scope: { enum: ["once", "project", "until_expiry"] } }, ["requestId", "decision"]),
78:  "policy.set": obj({ projectId: ID, policy: { type: "object" }, combos: obj({ claude: COMBO, codex: COMBO }) }, ["projectId", "policy"]),
79:  "user_input.answer": obj({ requestId: ID, answers: { type: "object", additionalProperties: { type: "string" } } }, ["requestId", "answers"]),
80:  "daemon.shutdown": EMPTY,
81:};
82:
83:export function methodClass(method: string): RpcMethodClass | null {
84:  for (const cls of Object.keys(RPC_METHODS) as RpcMethodClass[]) {
85:    if ((RPC_METHODS[cls] as readonly string[]).includes(method)) return cls;
86:  }
87:  return null;
88:}
89:export const isRpcMethod = (method: string): method is RpcMethod => methodClass(method) !== null;
90:
91:type Validator = ((x: unknown) => boolean) & { errors?: { instancePath: string; message?: string; params?: Record<string, unknown> }[] | null };
92:const validators = new Map<RpcMethod, Validator>();
93:let ajv: Ajv | undefined;
94:
95:/** params(?�략 ??`{}`)�?메서???�키마로 검증해 ?�류 문자??목록???�려준??�?배열 = ?�상). */
96:export function validateParams(method: RpcMethod, params: unknown): string[] {
97:  let v = validators.get(method);
98:  if (!v) {
99:    ajv ??= new Ajv({ allErrors: true, strict: true });
100:    v = ajv.compile(RPC_PARAMS_SCHEMA[method]) as Validator;
101:    validators.set(method, v);
102:  }
103:  const input = params === undefined ? {} : params;
104:  if (v(input)) return [];
105:  return (v.errors ?? []).map((e) => {
106:    const extra = e.params && "additionalProperty" in e.params ? ` (${String(e.params.additionalProperty)})` : "";
107:    return `${e.instancePath || "/"}: ${e.message ?? "invalid"}${extra}`;
108:  });
109:}
1:/** 최소 UI(P01 T7): Task 목록·lastAppliedSeq·보류 승인 수 + "빈 Task 제출" 버튼(`rpc.write('task.submit')`). */
2:import { useCallback, useState, useSyncExternalStore } from "react";
3:import type { AppStore } from "./store.js";
4:
5:export function App({ store, api }: { store: AppStore; api: Window["agentStudio"] }) {
6:  const snap = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot);
7:  const [error, setError] = useState<string | null>(null);
8:  const tasks = Object.values(snap.tasks);
9:  const pendingCount = Object.keys(snap.pendingApprovals).length;
10:  const submit = useCallback(() => {
11:    if (!api) return setError("preload API 없음");
12:    api.rpc.write("task.submit", { title: `empty task ${tasks.length + 1}`, kind: "impl" }).then(
13:      () => setError(null),
14:      (e: unknown) => setError(e instanceof Error ? e.message : String(e)),
15:    );
16:  }, [api, tasks.length]);
17:  return (
18:    <main>
19:      <header>
20:        <h1>Agent Studio</h1>
21:        <p className="meta">
22:          seq <strong data-testid="last-seq">{snap.lastAppliedSeq}</strong> · 보류 승인 <strong data-testid="pending-count">{pendingCount}</strong> · preload {api ? "연결" : "없음"}
23:        </p>
24:      </header>
25:      <section>
26:        <button type="button" onClick={submit} data-testid="submit-empty-task">
27:          빈 Task 제출
28:        </button>
29:        {error && (
30:          <p className="error" role="alert">
31:            {error}
32:          </p>
33:        )}
34:      </section>
35:      <section>
36:        <h2>Tasks ({tasks.length})</h2>
37:        <ul data-testid="task-list">
38:          {tasks.map((t) => (
39:            <li key={t.id}>
40:              <code>{t.id}</code> {t.title} — <span className={`status status-${t.status.toLowerCase()}`}>{t.status}</span>
41:            </li>
42:          ))}
43:        </ul>
44:      </section>
45:    </main>
46:  );
47:}
